import functools

def solve_minimax(cards):
    # cards is a tuple of available cards
    # turn: 0 for Grogg (min), 1 for Winnie (max)
    # diff: current sum of Pile 1 - sum of Pile 2

    @functools.lru_cache(None)
    def play(remaining, diff, turn):
        if not remaining:
            return abs(diff)

        if turn == 0: # Grogg's turn (minimize)
            best_val = float('inf')
            for card in remaining:
                # Grogg chooses card and pile
                # Pile 1
                val1 = play(tuple(c for c in remaining if c != card), diff + card, 1)
                # Pile 2
                val2 = play(tuple(c for c in remaining if c != card), diff - card, 1)
                best_val = min(best_val, val1, val2)
            return best_val
        else: # Winnie's turn (maximize)
            best_val = float('-inf')
            for card in remaining:
                # Winnie chooses card and pile
                # Pile 1
                val1 = play(tuple(c for c in remaining if c != card), diff + card, 0)
                # Pile 2
                val2 = play(tuple(c for c in remaining if c != card), diff - card, 0)
                best_val = max(best_val, val1, val2)
            return best_val

    return play(tuple(cards), 0, 0)

for n in range(1, 11):
    print(f"N={n}: {solve_minimax(range(1, n+1))}")

