import functools

def solve_minimax(cards):
    @functools.lru_cache(None)
    def play(remaining, diff, turn):
        if not remaining:
            return abs(diff)
        if turn == 0: # Grogg
            best_val = float('inf')
            best_card = None
            best_sign = None
            for card in remaining:
                for sign in [1, -1]:
                    val = play(tuple(c for c in remaining if c != card), diff + sign * card, 1)
                    if val < best_val:
                        best_val = val
                        best_card = card
                        best_sign = sign
            return best_val
        else: # Winnie
            best_val = float('-inf')
            best_card = None
            best_sign = None
            for card in remaining:
                for sign in [1, -1]:
                    val = play(tuple(c for c in remaining if c != card), diff + sign * card, 0)
                    if val > best_val:
                        best_val = val
                        best_card = card
                        best_sign = sign
            return best_val

    # To trace the game, we can't use lru_cache simply.
    # Let's just use the original solve_minimax and then manually trace.
    return play(tuple(cards), 0, 0)

print(f"N=4: {solve_minimax(range(1, 5))}")
